"""Author the rear cup with vendor clocking preserved; keep the canonical bench unchanged."""
import json
from pathlib import Path
from run_native import rpc
from fetch_exports import fetch
ROOT=Path(__file__).resolve().parents[1]
s='\n'.join((ROOT/'source'/p).read_text()for p in ['native_documents.py','intent_geometry.py','cohesive_limb_intent.py','paired_roll_intent.py','cohesive_crank_intent.py','cohesive_carrier_intent.py','paired_cup_intent.py','paired_rear_cup_intent.py'])+'''
def run(_context:str):
 import json,os,tempfile,time
 app=core.Application.get();doc=authoring_document(app,'leg');assert doc==app.activeDocument or doc.activate();d=fusion.Design.cast(app.activeProduct);assert d.activateRootComponent();root=d.rootComponent;tick=time.monotonic();key='motor_carrier_-1';assert not any(c.partNumber=='CANDIDATE_pr_'+key for c in d.allComponents);front=next(c for c in d.allComponents if c.partNumber=='CANDIDATE_pr_motor_carrier_1');before={'features':front.features.count,'faces':front.bRepBodies.item(0).faces.count,'volume':front.bRepBodies.item(0).getPhysicalProperties(fusion.CalculationAccuracy.VeryHighCalculationAccuracy).volume};o=root.occurrences.addNewComponent(core.Matrix3D.create());o.isLightBulbOn=False;c=o.component;c.name='Rear motor cup with correctly clocked ports';c.partNumber='CANDIDATE_pr_'+key;body=RearPairedCupIntent(IntentGeometry(d,c)).cup();assert c.bRepBodies.count==1;assert all(f.healthState==fusion.FeatureHealthStates.HealthyFeatureHealthState for f in c.features);body.name=c.name;o.isLightBulbOn=True;body.isLightBulbOn=True;path=os.path.join(tempfile.gettempdir(),'tinfox-native','paired-native-'+key+'.step');assert d.exportManager.execute(d.exportManager.createSTEPExportOptions(path,c));assert os.path.getsize(path)>100000;o.isLightBulbOn=False;after={'features':front.features.count,'faces':front.bRepBodies.item(0).faces.count,'volume':front.bRepBodies.item(0).getPhysicalProperties(fusion.CalculationAccuracy.VeryHighCalculationAccuracy).volume};assert before==after;print(json.dumps({'saved':False,'part':key,'features':c.features.count,'sketches':c.sketches.count,'faces':body.faces.count,'edges':body.edges.count,'path':path,'canonical_front_unchanged':True,'elapsed_seconds':time.monotonic()-tick,'scope':'Rear whole-robot migration candidate only. Canonical Leg20 bench and its export allowlist are unchanged.'}))
'''
r=rpc(s,'paired-rear-cup-native',timeout=900);assert r[0]['success'],r;record=json.loads(r[0]['message']);(ROOT/'audits/paired-rear-cup-native.json').write_text(json.dumps(record,indent=2));fetch(record['path'],Path(record['path']).name);print(record)
